// ArthaTech update 7: audit log, Team Head login, users page, real dashboard, edit project, confirm popups, houses search.
// Run inside your project folder (the one with package.json):  node update-ui-7.mjs
// It overwrites 16 files (listed when it runs).
import fs from "node:fs";
import path from "node:path";

const target = process.cwd();
const files = {
 "src/components/Confirm.jsx": "import { createContext, useCallback, useContext, useRef, useState } from \"react\";\nimport { Button, Modal } from \"./ui.jsx\";\n\nconst ConfirmContext = createContext(null);\n\n/** Wrap the app once. Then any component can do:  if (!(await confirm({ message }))) return;  */\nexport function ConfirmProvider({ children }) {\n  const [state, setState] = useState(null);\n  const resolver = useRef(null);\n\n  const confirm = useCallback(\n    (options) =>\n      new Promise((resolve) => {\n        resolver.current = resolve;\n        setState(options);\n      }),\n    []\n  );\n\n  const close = (result) => {\n    resolver.current?.(result);\n    resolver.current = null;\n    setState(null);\n  };\n\n  return (\n    <ConfirmContext.Provider value={confirm}>\n      {children}\n      {state && (\n        <Modal title={state.title || \"Are you sure?\"} onClose={() => close(false)}>\n          <p className=\"text-sm leading-relaxed text-ink/70\">{state.message}</p>\n          <div className=\"mt-6 flex gap-3\">\n            <Button variant=\"outline\" className=\"flex-1\" onClick={() => close(false)}>\n              Cancel\n            </Button>\n            <Button variant=\"dark\" className=\"flex-1\" onClick={() => close(true)}>\n              {state.confirmLabel || \"Confirm\"}\n            </Button>\n          </div>\n        </Modal>\n      )}\n    </ConfirmContext.Provider>\n  );\n}\n\nexport function useConfirm() {\n  const confirm = useContext(ConfirmContext);\n  if (!confirm) throw new Error(\"useConfirm must be used inside <ConfirmProvider>\");\n  return confirm;\n}\n",
 "src/lib/projectMeta.js": "// Shared project labels and form definition, used by the house and project pages.\n\nexport const TYPES = [\n  { value: \"movie\", label: \"Movie\" },\n  { value: \"ott_series\", label: \"OTT series\" },\n  { value: \"ad\", label: \"Ad\" },\n  { value: \"other\", label: \"Other\" },\n];\n\nexport const STATUSES = [\n  { value: \"draft\", label: \"Draft\" },\n  { value: \"planning\", label: \"Planning\" },\n  { value: \"active\", label: \"Active\" },\n  { value: \"wrapped\", label: \"Wrapped\" },\n  { value: \"closed\", label: \"Closed\" },\n];\n\nexport const label = (list, value) => list.find((x) => x.value === value)?.label || value || \"—\";\n\nexport const fmtDate = (s) =>\n  s ? new Date(s).toLocaleDateString(\"en-IN\", { day: \"2-digit\", month: \"short\", year: \"numeric\" }) : \"—\";\n\nexport const fmtDateTime = (s) =>\n  s\n    ? new Date(s).toLocaleString(\"en-IN\", {\n        day: \"2-digit\",\n        month: \"short\",\n        year: \"numeric\",\n        hour: \"2-digit\",\n        minute: \"2-digit\",\n      })\n    : \"—\";\n\nexport const PROJECT_FIELDS = [\n  { name: \"name\", label: \"Project name\", required: true },\n  { name: \"project_type\", label: \"Type\", as: \"select\", options: TYPES, required: true },\n  { name: \"status\", label: \"Status\", as: \"select\", options: STATUSES },\n  { name: \"start_date\", label: \"Start date\", type: \"date\" },\n  { name: \"end_date\", label: \"End date\", type: \"date\" },\n];\n\n/** Send only the fields that have a value */\nexport function projectToBody(v) {\n  const body = { name: v.name.trim(), project_type: v.project_type };\n  if (v.status) body.status = v.status;\n  if (v.start_date) body.start_date = v.start_date;\n  if (v.end_date) body.end_date = v.end_date;\n  return body;\n}\n",
 "src/api/audit.js": "import { api } from \"./client\";\n\n// ASSUMPTION: your API list has no audit endpoint yet. This calls GET /audit-logs.\n// When the backend adds it, change AUDIT_PATH below if the address is different.\nexport const AUDIT_PATH = \"/audit-logs\";\n\nexport const listAudit = () => api(AUDIT_PATH);\n\nconst text = (v) => {\n  if (v === null || v === undefined) return \"\";\n  if (typeof v === \"string\" || typeof v === \"number\") return String(v);\n  return v.email || v.full_name || v.name || v.code || JSON.stringify(v);\n};\n\n/** Reads common field names, so small differences in the backend response still work. */\nexport function normalizeAudit(data) {\n  const list = Array.isArray(data) ? data : data?.results || data?.logs || data?.data || [];\n  return list.map((e, i) => ({\n    key: e.id ?? i,\n    when: e.created_at ?? e.timestamp ?? e.at ?? e.time ?? e.date ?? null,\n    who: text(e.actor_email ?? e.actor ?? e.user_email ?? e.user ?? e.performed_by) || \"System\",\n    role: text(e.actor_role ?? e.role),\n    action: text(e.action ?? e.event ?? e.event_type ?? e.verb),\n    target: [text(e.target ?? e.object ?? e.entity ?? e.model ?? e.object_type), text(e.object_id ?? e.target_id)]\n      .filter(Boolean)\n      .join(\" #\"),\n    detail: e.detail ?? e.details ?? e.message ?? e.description ?? e.changes ?? e.metadata ?? null,\n    ip: text(e.ip ?? e.ip_address),\n    raw: e,\n  }));\n}\n",
 "src/api/users.js": "import { api } from \"./client\";\n\nexport const listUsers = ({ search, role_code, organisation_id } = {}) => {\n  const q = new URLSearchParams();\n  if (search) q.set(\"search\", search);\n  if (role_code) q.set(\"role_code\", role_code);\n  if (organisation_id) q.set(\"organisation_id\", organisation_id);\n  const qs = q.toString();\n  return api(`/users${qs ? `?${qs}` : \"\"}`);\n};\n\n/** Returns { profile_id, user_id, generated_password } - show the password once, never store it. */\nexport const createUser = (body) => api(\"/users\", { method: \"POST\", body });\n\nexport const updateUser = (userId, body) => api(`/users/${userId}`, { method: \"PATCH\", body });\nexport const updateProfile = (profileId, body) => api(`/profiles/${profileId}`, { method: \"PATCH\", body });\n\n/** Returns { generated_password } - show once. */\nexport const resetPassword = (userId) => api(`/users/${userId}/reset-password`, { method: \"POST\" });\n\n/** action: lock | unlock | deactivate | activate */\nexport const userAction = (userId, action) => api(`/users/${userId}/${action}`, { method: \"POST\" });\n\n/** Replaces the WHOLE list. Send [] to clear. */\nexport const setProfilePermissions = (profileId, permissions) =>\n  api(`/profiles/${profileId}/permissions`, { method: \"PUT\", body: { permissions } });\n\nexport const listOrganisations = () => api(\"/organisations\");\n\n/**\n * GET /users returns one entry per PERSON, with a \"profiles\" list (one per role / hat):\n *   { id, email, full_name, is_active, is_locked, profiles: [\n *       { profile_id, is_active, role:{code,name}, organisation:{id,name},\n *         project:{id,name}|null, teams:[], team_member_id, extra_permissions:[] } ] }\n * We make one row per PROFILE, because permissions, role and project belong to a profile.\n */\nexport function normalizeUsers(data) {\n  const list = Array.isArray(data) ? data : data?.results || data?.users || data?.data || [];\n  const rows = [];\n  for (const u of list) {\n    const profiles = Array.isArray(u.profiles) && u.profiles.length ? u.profiles : [null];\n    for (const p of profiles) {\n      const userId = u.id ?? u.user_id;\n      const profileId = p?.profile_id ?? p?.id ?? null;\n      rows.push({\n        raw: u,\n        key: `${userId}-${profileId ?? \"x\"}`,\n        userId,\n        profileId,\n        email: u.email ?? \"\",\n        name: u.full_name ?? \"\",\n        roleCode: p?.role?.code ?? \"\",\n        roleName: p?.role?.name ?? \"\",\n        orgId: p?.organisation?.id ?? null,\n        orgName: p?.organisation?.name ?? \"\",\n        projectId: p?.project?.id ?? null,\n        projectName: p?.project?.name ?? \"\",\n        teams: p?.teams ?? [],\n        active: (u.is_active ?? true) && (p?.is_active ?? true),\n        profileActive: p?.is_active ?? true,\n        teamMemberId: p?.team_member_id ?? null,\n        lastLogin: u.last_login_at ?? null,\n        mustChange: Boolean(u.must_change_password),\n        locked: Boolean(u.is_locked),\n        extra: p?.extra_permissions ?? [],\n      });\n    }\n  }\n  return rows;\n}\n",
 "src/pages/AuditLogPage.jsx": "import { useEffect, useMemo, useState } from \"react\";\nimport * as auditApi from \"../api/audit\";\nimport { Alert, Button, Spinner } from \"../components/ui.jsx\";\nimport { errorText } from \"../lib/errors.js\";\nimport { fmtDateTime } from \"../lib/projectMeta.js\";\n\nfunction Detail({ value }) {\n  if (value === null || value === undefined || value === \"\") return <span className=\"text-ink/35\">—</span>;\n  if (typeof value === \"string\" || typeof value === \"number\") return <span>{String(value)}</span>;\n  return (\n    <details className=\"text-xs\">\n      <summary className=\"cursor-pointer font-semibold text-brand\">View changes</summary>\n      <pre className=\"mt-1 max-w-md overflow-auto rounded-lg bg-mist p-2\">{JSON.stringify(value, null, 1)}</pre>\n    </details>\n  );\n}\n\nexport default function AuditLogPage() {\n  const [rows, setRows] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n  const [q, setQ] = useState(\"\");\n  const [action, setAction] = useState(\"\");\n  const [from, setFrom] = useState(\"\");\n  const [to, setTo] = useState(\"\");\n\n  async function load() {\n    setLoading(true);\n    try {\n      setRows(auditApi.normalizeAudit(await auditApi.listAudit()));\n      setError(null);\n    } catch (e) {\n      setError(e);\n      setRows([]);\n    } finally {\n      setLoading(false);\n    }\n  }\n\n  useEffect(() => {\n    load();\n  }, []);\n\n  const actions = useMemo(() => [...new Set(rows.map((r) => r.action).filter(Boolean))].sort(), [rows]);\n\n  const visible = rows.filter((r) => {\n    if (action && r.action !== action) return false;\n    if (from && (!r.when || new Date(r.when) < new Date(from))) return false;\n    if (to && (!r.when || new Date(r.when) > new Date(`${to}T23:59:59`))) return false;\n    if (q.trim()) {\n      const hay = `${r.who} ${r.role} ${r.action} ${r.target} ${r.ip} ${JSON.stringify(r.detail ?? \"\")}`.toLowerCase();\n      if (!hay.includes(q.trim().toLowerCase())) return false;\n    }\n    return true;\n  });\n\n  const notBuilt = error && (error.status === 404 || error.code === \"not_found\");\n\n  return (\n    <div className=\"space-y-6\">\n      <div className=\"flex flex-wrap items-end justify-between gap-4\">\n        <div>\n          <p className=\"text-sm font-bold uppercase tracking-widest text-brand\">Platform</p>\n          <h1 className=\"mt-1 text-4xl font-black tracking-tight\">Audit log</h1>\n          <p className=\"mt-1 text-sm text-ink/60\">Who did what, and when.</p>\n        </div>\n        <Button variant=\"outline\" onClick={load}>\n          Refresh\n        </Button>\n      </div>\n\n      {notBuilt ? (\n        <div className=\"rounded-2xl border border-dashed border-ink/25 bg-white/70 p-8\">\n          <p className=\"text-lg font-extrabold\">The audit log is not available on the server yet</p>\n          <p className=\"mt-1 text-sm text-ink/65\">\n            This screen calls <code className=\"rounded bg-mist px-1.5 py-0.5\">GET {auditApi.AUDIT_PATH}</code> and the server\n            answered \"not found\". Ask your backend developer to add it. If the address is different, change{\" \"}\n            <code className=\"rounded bg-mist px-1.5 py-0.5\">AUDIT_PATH</code> in <code>src/api/audit.js</code>.\n          </p>\n        </div>\n      ) : (\n        <>\n          <Alert>{error && errorText(error)}</Alert>\n\n          <div className=\"grid gap-3 sm:grid-cols-2 lg:grid-cols-4\">\n            <input className=\"input\" placeholder=\"Search who, action, details…\" value={q} onChange={(e) => setQ(e.target.value)} />\n            <select className=\"input\" value={action} onChange={(e) => setAction(e.target.value)}>\n              <option value=\"\">All actions</option>\n              {actions.map((a) => (\n                <option key={a} value={a}>\n                  {a}\n                </option>\n              ))}\n            </select>\n            <input className=\"input\" type=\"date\" value={from} onChange={(e) => setFrom(e.target.value)} aria-label=\"From date\" />\n            <input className=\"input\" type=\"date\" value={to} onChange={(e) => setTo(e.target.value)} aria-label=\"To date\" />\n          </div>\n\n          <div className=\"overflow-x-auto rounded-2xl border border-line bg-white\">\n            <table className=\"w-full min-w-[52rem] text-left text-sm\">\n              <thead>\n                <tr className=\"border-b border-line text-xs uppercase tracking-wider text-ink/45\">\n                  <th className=\"px-4 py-3 font-bold\">When</th>\n                  <th className=\"px-4 py-3 font-bold\">Who</th>\n                  <th className=\"px-4 py-3 font-bold\">Action</th>\n                  <th className=\"px-4 py-3 font-bold\">On</th>\n                  <th className=\"px-4 py-3 font-bold\">Details</th>\n                </tr>\n              </thead>\n              <tbody className=\"divide-y divide-line align-top\">\n                {loading && (\n                  <tr>\n                    <td colSpan={5} className=\"px-4 py-10 text-center\">\n                      <Spinner className=\"mx-auto h-5 w-5 text-brand\" />\n                    </td>\n                  </tr>\n                )}\n                {!loading && visible.length === 0 && (\n                  <tr>\n                    <td colSpan={5} className=\"px-4 py-10 text-center text-ink/50\">\n                      No entries found.\n                    </td>\n                  </tr>\n                )}\n                {!loading &&\n                  visible.map((r) => (\n                    <tr key={r.key}>\n                      <td className=\"whitespace-nowrap px-4 py-3 text-ink/70\">{fmtDateTime(r.when)}</td>\n                      <td className=\"px-4 py-3\">\n                        <p className=\"font-semibold\">{r.who}</p>\n                        {r.role && <p className=\"text-xs text-ink/50\">{r.role}</p>}\n                      </td>\n                      <td className=\"px-4 py-3 font-semibold\">{r.action || \"—\"}</td>\n                      <td className=\"px-4 py-3 text-ink/70\">{r.target || \"—\"}</td>\n                      <td className=\"px-4 py-3\">\n                        <Detail value={r.detail} />\n                        {r.ip && <p className=\"mt-1 text-xs text-ink/40\">IP {r.ip}</p>}\n                      </td>\n                    </tr>\n                  ))}\n              </tbody>\n            </table>\n          </div>\n          {!loading && <p className=\"text-xs text-ink/50\">{visible.length} of {rows.length} entries</p>}\n        </>\n      )}\n    </div>\n  );\n}\n",
 "src/pages/UsersPage.jsx": "import { useCallback, useEffect, useState } from \"react\";\nimport * as usersApi from \"../api/users\";\nimport { useAuth } from \"../features/auth/AuthContext.jsx\";\nimport CreateUserModal from \"../features/users/CreateUserModal.jsx\";\nimport EditUserModal from \"../features/users/EditUserModal.jsx\";\nimport PasswordModal from \"../features/users/PasswordModal.jsx\";\nimport PermissionsModal from \"../features/users/PermissionsModal.jsx\";\nimport { Alert, Badge, Button, Spinner } from \"../components/ui.jsx\";\nimport { useConfirm } from \"../components/Confirm.jsx\";\nimport { errorText } from \"../lib/errors.js\";\nimport { fmtDateTime } from \"../lib/projectMeta.js\";\nimport { ROLES, roleName } from \"../lib/roles.js\";\n\nexport default function UsersPage() {\n  const { can } = useAuth();\n  const confirm = useConfirm();\n  const [search, setSearch] = useState(\"\");\n  const [role, setRole] = useState(\"\");\n  const [orgId, setOrgId] = useState(\"\");\n  const [orgs, setOrgs] = useState([]);\n  const [rows, setRows] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n  const [notice, setNotice] = useState(\"\");\n  const [busyKey, setBusyKey] = useState(null);\n\n  const [showCreate, setShowCreate] = useState(false);\n  const [secret, setSecret] = useState(null); // { title, email, password } - cleared when the modal closes\n  const [permFor, setPermFor] = useState(null);\n  const [editFor, setEditFor] = useState(null);\n\n  useEffect(() => {\n    usersApi\n      .listOrganisations()\n      .then((d) => setOrgs(Array.isArray(d) ? d : d?.results || []))\n      .catch(() => setOrgs([]));\n  }, []);\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    try {\n      const data = await usersApi.listUsers({ search: search.trim(), role_code: role, organisation_id: orgId });\n      setRows(usersApi.normalizeUsers(data));\n      setError(null);\n    } catch (e) {\n      setError(e);\n    } finally {\n      setLoading(false);\n    }\n  }, [search, role, orgId]);\n\n  // Wait a little while the person types in the search box\n  useEffect(() => {\n    const t = setTimeout(load, 300);\n    return () => clearTimeout(t);\n  }, [load]);\n\n  const canCreate = can(\"users.create.user\") || can(\"users.create.admin\");\n  const suffix = (u) => (u.roleCode === \"admin\" ? \"admin\" : \"user\");\n\n  async function run(u, action, doneText) {\n    if (action === \"deactivate\") {\n      const ok = await confirm({\n        title: \"Deactivate this person?\",\n        message: `${u.email} will not be able to log in until you activate them again.`,\n        confirmLabel: \"Deactivate\",\n      });\n      if (!ok) return;\n    }\n    setBusyKey(u.key);\n    setNotice(\"\");\n    setError(null);\n    try {\n      if (action === \"reset\") {\n        const res = await usersApi.resetPassword(u.userId);\n        setSecret({ title: \"Password reset\", email: u.email, password: res.generated_password });\n      } else {\n        await usersApi.userAction(u.userId, action);\n        setNotice(`${doneText}: ${u.email}`);\n        await load();\n      }\n    } catch (e) {\n      setError(e);\n    } finally {\n      setBusyKey(null);\n    }\n  }\n\n  return (\n    <div className=\"space-y-6\">\n      <div className=\"flex flex-wrap items-end justify-between gap-4\">\n        <div>\n          <p className=\"text-sm font-bold uppercase tracking-widest text-brand\">Admin</p>\n          <h1 className=\"mt-1 text-4xl font-black tracking-tight\">Users</h1>\n        </div>\n        {canCreate && <Button onClick={() => setShowCreate(true)}>+ New user</Button>}\n      </div>\n\n      <div className=\"flex flex-col gap-3 sm:flex-row\">\n        <input\n          className=\"input sm:max-w-xs\"\n          placeholder=\"Search name or email…\"\n          value={search}\n          onChange={(e) => setSearch(e.target.value)}\n        />\n        <select className=\"input sm:max-w-[12rem]\" value={role} onChange={(e) => setRole(e.target.value)}>\n          <option value=\"\">All roles</option>\n          {ROLES.map((r) => (\n            <option key={r.code} value={r.code}>\n              {r.name}\n            </option>\n          ))}\n        </select>\n        <select className=\"input sm:max-w-[12rem]\" value={orgId} onChange={(e) => setOrgId(e.target.value)}>\n          <option value=\"\">All houses</option>\n          {orgs.map((o) => (\n            <option key={o.id} value={o.id}>\n              {o.name}\n            </option>\n          ))}\n        </select>\n      </div>\n\n      {notice && <Alert tone=\"success\">{notice}</Alert>}\n      <Alert>{error && errorText(error)}</Alert>\n\n      <div className=\"overflow-x-auto rounded-2xl border border-line bg-white\">\n        <table className=\"w-full min-w-[56rem] text-left text-sm\">\n          <thead>\n            <tr className=\"border-b border-line text-xs uppercase tracking-wider text-ink/45\">\n              <th className=\"px-4 py-3 font-bold\">User</th>\n              <th className=\"px-4 py-3 font-bold\">Role</th>\n              <th className=\"px-4 py-3 font-bold\">House / project</th>\n              <th className=\"px-4 py-3 font-bold\">Status</th>\n              <th className=\"px-4 py-3 font-bold\">Last login</th>\n              <th className=\"px-4 py-3 text-right font-bold\">Actions</th>\n            </tr>\n          </thead>\n          <tbody className=\"divide-y divide-line\">\n            {loading && (\n              <tr>\n                <td colSpan={6} className=\"px-4 py-10 text-center text-ink/50\">\n                  <Spinner className=\"mx-auto h-5 w-5 text-brand\" />\n                </td>\n              </tr>\n            )}\n            {!loading && rows.length === 0 && (\n              <tr>\n                <td colSpan={6} className=\"px-4 py-10 text-center text-ink/50\">\n                  No users found.\n                </td>\n              </tr>\n            )}\n            {!loading &&\n              rows.map((u) => {\n                const busy = busyKey === u.key;\n                const act = \"cursor-pointer rounded-md px-2 py-1 text-xs font-semibold hover:bg-mist disabled:opacity-40\";\n                return (\n                  <tr key={u.key} className=\"align-middle\">\n                    <td className=\"px-4 py-3\">\n                      <p className=\"font-bold\">{u.name || \"—\"}</p>\n                      <p className=\"text-xs text-ink/50\">{u.email}</p>\n                    </td>\n                    <td className=\"px-4 py-3\">{u.roleName || roleName(u.roleCode)}</td>\n                    <td className=\"px-4 py-3 text-ink/60\">\n                      <p>{u.orgName || \"Platform\"}</p>\n                      {(u.projectName || u.teams.length > 0) && (\n                        <p className=\"text-xs text-ink/45\">\n                          {[u.projectName, u.teams.map((t) => t.name).join(\", \")].filter(Boolean).join(\" · \")}\n                        </p>\n                      )}\n                    </td>\n                    <td className=\"space-y-1 px-4 py-3\">\n                      <div className=\"flex flex-wrap gap-1\">\n                        <Badge tone={u.active ? \"dark\" : \"neutral\"}>{u.active ? \"Active\" : \"Inactive\"}</Badge>\n                        {u.locked && <Badge tone=\"red\">Locked</Badge>}\n                      </div>\n                      {u.mustChange && <Badge tone=\"red\">Must change password</Badge>}\n                    </td>\n                    <td className=\"whitespace-nowrap px-4 py-3 text-xs text-ink/60\">\n                      {u.lastLogin ? fmtDateTime(u.lastLogin) : \"Never\"}\n                    </td>\n                    <td className=\"px-4 py-3\">\n                      <div className=\"flex flex-wrap justify-end gap-1\">\n                        {canCreate && (\n                          <button disabled={busy} className={act} onClick={() => setEditFor(u)}>\n                            Edit\n                          </button>\n                        )}\n                        {can(`users.reset_password.${suffix(u)}`) && (\n                          <button disabled={busy} className={act} onClick={() => run(u, \"reset\")}>\n                            Reset password\n                          </button>\n                        )}\n                        {can(`users.deactivate.${suffix(u)}`) && (\n                          <>\n                            <button\n                              disabled={busy}\n                              className={act}\n                              onClick={() => run(u, u.locked ? \"unlock\" : \"lock\", u.locked ? \"Unlocked\" : \"Locked\")}\n                            >\n                              {u.locked ? \"Unlock\" : \"Lock\"}\n                            </button>\n                            <button\n                              disabled={busy}\n                              className={`${act} ${u.active ? \"text-brand\" : \"\"}`}\n                              onClick={() => run(u, u.active ? \"deactivate\" : \"activate\", u.active ? \"Deactivated\" : \"Activated\")}\n                            >\n                              {u.active ? \"Deactivate\" : \"Activate\"}\n                            </button>\n                          </>\n                        )}\n                        {can(\"profile_permission.manage\") && u.profileId && (\n                          <button disabled={busy} className={act} onClick={() => setPermFor(u)}>\n                            Permissions\n                          </button>\n                        )}\n                      </div>\n                    </td>\n                  </tr>\n                );\n              })}\n          </tbody>\n        </table>\n      </div>\n\n      {showCreate && (\n        <CreateUserModal\n          onClose={() => setShowCreate(false)}\n          onCreated={({ email, password }) => {\n            setShowCreate(false);\n            setSecret({ title: \"User created\", email, password });\n            load();\n          }}\n        />\n      )}\n      {editFor && (\n        <EditUserModal\n          target={editFor}\n          onClose={() => setEditFor(null)}\n          onSaved={() => {\n            setNotice(`Saved: ${editFor.email}`);\n            setEditFor(null);\n            load();\n          }}\n        />\n      )}\n      {secret && <PasswordModal {...secret} onClose={() => setSecret(null)} />}\n      {permFor && (\n        <PermissionsModal\n          target={permFor}\n          onClose={() => setPermFor(null)}\n          onSaved={() => {\n            setNotice(`Permissions saved: ${permFor.email}`);\n            setPermFor(null);\n            load();\n          }}\n        />\n      )}\n    </div>\n  );\n}\n",
 "src/pages/DashboardPage.jsx": "import { useEffect, useState } from \"react\";\nimport { Link } from \"react-router-dom\";\nimport * as houses from \"../api/houses\";\nimport * as usersApi from \"../api/users\";\nimport { useAuth } from \"../features/auth/AuthContext.jsx\";\nimport { Badge, Spinner } from \"../components/ui.jsx\";\nimport { formatPaiseShort } from \"../lib/money.js\";\nimport { STATUSES, fmtDate, label } from \"../lib/projectMeta.js\";\n\n/** Real numbers only, built from the houses, projects, teams and users the server already returns. */\nexport default function DashboardPage() {\n  const { user, profile, can } = useAuth();\n  const first = (user?.full_name || user?.email || \"\").split(/[\\s@]/)[0];\n  const canHouses = can(\"house.create\") || can(\"project.view\");\n  const canUsers = can(\"users.view\");\n  const canBudget = can(\"team.budget.set\");\n\n  const [stats, setStats] = useState({ data: null, loading: true });\n\n  useEffect(() => {\n    let alive = true;\n    (async () => {\n    const hs = canHouses ? houses.asList(await houses.listHouses()) : [];\n    const projects = hs.flatMap((h) => (h.projects || []).map((p) => ({ ...p, houseName: h.name, orgId: h.id })));\n\n    // Teams for up to 30 projects (one call each)\n    const teamLists = await Promise.all(\n      projects.slice(0, 30).map((p) =>\n        houses\n          .listTeams(p.id)\n          .then(houses.asList)\n          .catch(() => [])\n      )\n    );\n    const teams = teamLists.flat();\n\n    let people = null;\n    if (canUsers) {\n      try {\n        people = usersApi.normalizeUsers(await usersApi.listUsers()).length;\n      } catch {\n        people = null;\n      }\n    }\n      return {\n      houses: hs,\n      projects,\n      teams: teams.length,\n      planned: teams.reduce((a, t) => a + (Number(t.headcount) || 0), 0),\n      budget: teams.reduce((a, t) => a + (Number(t.budget_paise) || 0), 0),\n      people,\n    };\n    })()\n      .then((data) => alive && setStats({ data, loading: false }))\n      .catch(() => alive && setStats({ data: null, loading: false }));\n    return () => {\n      alive = false;\n    };\n  }, [canHouses, canUsers]);\n\n  const s = stats.data;\n  const tiles = s\n    ? [\n        ...(canHouses\n          ? [\n              { label: \"Houses\", value: s.houses.length },\n              { label: \"Projects\", value: s.projects.length, sub: `${s.projects.filter((p) => p.status === \"active\").length} active` },\n              { label: \"Teams\", value: s.teams, sub: `${s.planned} people planned` },\n            ]\n          : []),\n        ...(canBudget && canHouses ? [{ label: \"Team budgets\", value: formatPaiseShort(s.budget) }] : []),\n        ...(s.people !== null ? [{ label: \"Users\", value: s.people }] : []),\n      ]\n    : [];\n\n  const recent = s ? [...s.projects].sort((a, b) => Number(b.id) - Number(a.id)).slice(0, 6) : [];\n\n  return (\n    <div className=\"space-y-8\">\n      <div>\n        <p className=\"text-sm font-bold uppercase tracking-widest text-brand\">Dashboard</p>\n        <h1 className=\"mt-1 text-4xl font-black tracking-tight\">Hello, {first}.</h1>\n        <p className=\"mt-1 text-ink/60\">\n          You are signed in as <b className=\"text-ink\">{profile?.role_name}</b>\n          {profile?.organisation_name ? ` at ${profile.organisation_name}` : \" on the platform\"}.\n        </p>\n      </div>\n\n      {stats.loading ? (\n        <div className=\"py-8 text-center\">\n          <Spinner className=\"mx-auto h-6 w-6 text-brand\" />\n        </div>\n      ) : (\n        <>\n          {tiles.length > 0 && (\n            <div className=\"grid grid-cols-2 gap-3 lg:grid-cols-5\">\n              {tiles.map((t, i) => (\n                <div key={t.label} className={`rounded-2xl p-5 ${i === 0 ? \"bg-ink text-white\" : \"border border-line bg-white\"}`}>\n                  <p className={`text-xs font-bold uppercase tracking-wider ${i === 0 ? \"text-white/50\" : \"text-ink/45\"}`}>{t.label}</p>\n                  <p className=\"mt-1 text-3xl font-black tracking-tight\">{t.value}</p>\n                  {t.sub && <p className={`mt-0.5 text-xs ${i === 0 ? \"text-white/50\" : \"text-ink/45\"}`}>{t.sub}</p>}\n                </div>\n              ))}\n            </div>\n          )}\n\n          {recent.length > 0 && (\n            <div className=\"rounded-2xl border border-line bg-white p-5\">\n              <div className=\"flex items-center justify-between\">\n                <h2 className=\"font-extrabold\">Projects</h2>\n                <Link to=\"/houses\" className=\"text-sm font-semibold text-brand hover:underline\">\n                  All houses →\n                </Link>\n              </div>\n              <ul className=\"mt-3 divide-y divide-line\">\n                {recent.map((p) => (\n                  <li key={p.id}>\n                    <Link\n                      to={`/projects/${p.id}`}\n                      state={{ name: p.name, orgId: p.orgId, houseName: p.houseName }}\n                      className=\"flex flex-wrap items-center justify-between gap-2 py-3 hover:text-brand\"\n                    >\n                      <span className=\"min-w-0\">\n                        <span className=\"block truncate font-bold\">{p.name}</span>\n                        <span className=\"block text-xs text-ink/50\">\n                          {p.houseName} · {fmtDate(p.start_date)} → {fmtDate(p.end_date)}\n                        </span>\n                      </span>\n                      <Badge tone={p.status === \"active\" ? \"dark\" : \"neutral\"}>{label(STATUSES, p.status)}</Badge>\n                    </Link>\n                  </li>\n                ))}\n              </ul>\n            </div>\n          )}\n\n          {tiles.length === 0 && recent.length === 0 && (\n            <div className=\"rounded-2xl border border-dashed border-ink/20 bg-white/60 p-10 text-center text-sm text-ink/60\">\n              Nothing to show yet. Your menu on the left has what your role can open.\n            </div>\n          )}\n        </>\n      )}\n    </div>\n  );\n}\n",
 "src/pages/ProjectDetailPage.jsx": "import { useState } from \"react\";\nimport { Link, useLocation, useParams } from \"react-router-dom\";\nimport * as houses from \"../api/houses\";\nimport * as usersApi from \"../api/users\";\nimport CreateUserModal from \"../features/users/CreateUserModal.jsx\";\nimport PasswordModal from \"../features/users/PasswordModal.jsx\";\nimport { roleName } from \"../lib/roles.js\";\nimport { useAuth } from \"../features/auth/AuthContext.jsx\";\nimport { useLoad } from \"../lib/useLoad.js\";\nimport { Alert, Badge, Button, Spinner } from \"../components/ui.jsx\";\nimport FormModal from \"../components/FormModal.jsx\";\nimport TeamCard from \"../features/projects/TeamCard.jsx\";\nimport { errorText } from \"../lib/errors.js\";\nimport { formatPaiseShort, rupeesToPaise } from \"../lib/money.js\";\nimport { useConfirm } from \"../components/Confirm.jsx\";\nimport { PROJECT_FIELDS, STATUSES, TYPES, fmtDate, label, projectToBody } from \"../lib/projectMeta.js\";\n\nexport default function ProjectDetailPage() {\n  const { projectId } = useParams();\n  const state = useLocation().state || {};\n  const { can } = useAuth();\n  const confirm = useConfirm();\n  // Find this project and its house from the houses list, so a page refresh still works\n  const houseQ = useLoad(() => houses.listHouses(), []);\n  const house = houseQ.data.find((h) => (h.projects || []).some((p) => String(p.id) === String(projectId)));\n  const project = house?.projects?.find((p) => String(p.id) === String(projectId));\n  const projectName = project?.name || state.name || `Project #${projectId}`;\n  const houseName = house?.name || state.houseName;\n  const canProject = can(\"project.create\");\n  const teams = useLoad(() => houses.listTeams(projectId), [projectId]);\n  const [modal, setModal] = useState(null); // { type: \"create\" | \"edit\", row? }\n  const [notice, setNotice] = useState(\"\");\n  const [showUser, setShowUser] = useState(false);\n  const [secret, setSecret] = useState(null);\n  const orgId = house?.id ?? state.orgId;\n  // People of this house, then keep only the ones assigned to this project\n  const people = useLoad(\n    async () =>\n      orgId\n        ? usersApi\n            .normalizeUsers(await usersApi.listUsers({ organisation_id: orgId }))\n            .filter((u) => String(u.orgId) === String(orgId))\n        : [],\n    [orgId]\n  );\n  const projectPeople = people.data.filter((u) => String(u.projectId) === String(projectId));\n  const canUser = can(\"users.create.user\") || can(\"users.create.admin\");\n  const [openIds, setOpenIds] = useState(null); // null = default (all open when 6 teams or fewer)\n\n  const canManage = can(\"team.manage\");\n  const canBudget = can(\"team.budget.set\");\n  const canAdvance = can(\"team.advance.set\");\n  const list = teams.data;\n\n  const isOpen = (id) => (openIds ? openIds.has(id) : list.length <= 6);\n  const toggle = (id) => {\n    const next = new Set(openIds ?? (list.length <= 6 ? list.map((t) => t.id) : []));\n    if (next.has(id)) next.delete(id);\n    else next.add(id);\n    setOpenIds(next);\n  };\n\n  const totals = list.reduce(\n    (a, t) => ({\n      people: a.people + (Number(t.headcount) || 0),\n      budget: a.budget + (Number(t.budget_paise) || 0),\n      advance: a.advance + (Number(t.advance_paise) || 0),\n    }),\n    { people: 0, budget: 0, advance: 0 }\n  );\n\n  // Money is typed in rupees and sent as whole paise. Only fields this person may set are shown.\n  const fields = [\n    { name: \"name\", label: \"Team name\", required: true },\n    { name: \"headcount\", label: \"Headcount\", type: \"number\", min: 0 },\n    ...(canBudget ? [{ name: \"budget\", label: \"Team budget (₹)\", type: \"number\", min: 0, hint: \"In rupees\" }] : []),\n    ...(canAdvance ? [{ name: \"advance\", label: \"Advance (₹)\", type: \"number\", min: 0, hint: \"In rupees\" }] : []),\n  ];\n\n  function toBody(v) {\n    const body = { name: v.name.trim() };\n    if (v.headcount !== \"\") body.headcount = Number(v.headcount);\n    if (canBudget && v.budget !== \"\") body.budget_paise = rupeesToPaise(v.budget);\n    if (canAdvance && v.advance !== \"\") body.advance_paise = rupeesToPaise(v.advance);\n    return body;\n  }\n  const rupees = (paise) => (paise === null || paise === undefined ? \"\" : String(paise / 100));\n\n  async function finish(message) {\n    setModal(null);\n    setNotice(message);\n    await teams.reload();\n  }\n\n  async function removeTeam(t) {\n    const ok = await confirm({\n      title: `Delete team ${t.name}?`,\n      message: \"This only works if it has no members, expenses or advances.\",\n      confirmLabel: \"Delete\",\n    });\n    if (!ok) return;\n    setNotice(\"\");\n    try {\n      await houses.deleteTeam(t.id);\n      await finish(`Deleted ${t.name}`);\n    } catch (e) {\n      teams.setError(e);\n    }\n  }\n\n  const tiles = [\n    { label: \"Teams\", value: list.length },\n    { label: \"People planned\", value: totals.people },\n    ...(canBudget ? [{ label: \"Team budgets\", value: formatPaiseShort(totals.budget) }] : []),\n    ...(canAdvance ? [{ label: \"Advances\", value: formatPaiseShort(totals.advance) }] : []),\n  ];\n\n  return (\n    <div className=\"space-y-6\">\n      <div className=\"flex flex-wrap items-end justify-between gap-4\">\n        <div>\n          <p className=\"text-sm font-semibold text-ink/55\">\n            <Link to=\"/houses\" className=\"hover:text-brand\">Houses</Link> /{\" \"}\n            {orgId ? (\n              <Link to={`/houses/${orgId}`} state={{ name: houseName }} className=\"hover:text-brand\">\n                {houseName || \"House\"}\n              </Link>\n            ) : (\n              \"House\"\n            )}{\" \"}\n            / {projectName}\n          </p>\n          <h1 className=\"mt-1 text-4xl font-black tracking-tight\">{projectName}</h1>\n          {project && (\n            <p className=\"mt-2 flex flex-wrap items-center gap-2 text-sm text-ink/60\">\n              <Badge tone={project.status === \"active\" ? \"dark\" : \"neutral\"}>{label(STATUSES, project.status)}</Badge>\n              <span>{label(TYPES, project.project_type)}</span>\n              <span>· {fmtDate(project.start_date)} → {fmtDate(project.end_date)}</span>\n            </p>\n          )}\n        </div>\n        <div className=\"flex gap-2\">\n          {list.length > 1 && (\n            <Button variant=\"outline\" onClick={() => setOpenIds(openIds && openIds.size === list.length ? new Set() : new Set(list.map((t) => t.id)))}>\n              {openIds && openIds.size === list.length ? \"Collapse all\" : \"Expand all\"}\n            </Button>\n          )}\n          {canProject && project && (\n            <Button variant=\"outline\" onClick={() => setModal({ type: \"project\" })}>\n              Edit project\n            </Button>\n          )}\n          {canManage && <Button onClick={() => setModal({ type: \"create\" })}>+ New team</Button>}\n        </div>\n      </div>\n\n      <div className=\"grid grid-cols-2 gap-3 lg:grid-cols-4\">\n        {tiles.map((t, i) => (\n          <div key={t.label} className={`rounded-2xl p-5 ${i === 0 ? \"bg-ink text-white\" : \"border border-line bg-white\"}`}>\n            <p className={`text-xs font-bold uppercase tracking-wider ${i === 0 ? \"text-white/50\" : \"text-ink/45\"}`}>{t.label}</p>\n            <p className=\"mt-1 text-2xl font-black tracking-tight\">{t.value}</p>\n          </div>\n        ))}\n      </div>\n\n      {/* People assigned to this project only */}\n      <div className=\"rounded-2xl border border-line bg-white p-5\">\n        <div className=\"flex flex-wrap items-center justify-between gap-2\">\n          <div>\n            <h2 className=\"font-extrabold\">People on this project</h2>\n            <p className=\"text-xs text-ink/55\">Producer, Project Manager and others who belong to this project only.</p>\n          </div>\n          {canUser && orgId && (\n            <Button variant=\"outline\" className=\"!py-2\" onClick={() => setShowUser(true)}>\n              + Add user to this project\n            </Button>\n          )}\n        </div>\n        {!orgId && (\n          <p className=\"mt-3 text-sm text-ink/55\">Open this project from its house page to manage its people.</p>\n        )}\n        {orgId && people.loading && <Spinner className=\"mt-3 h-5 w-5 text-brand\" />}\n        {orgId && !people.loading && projectPeople.length === 0 && (\n          <p className=\"mt-3 text-sm text-ink/55\">Nobody is assigned to this project yet. Add the Producer first.</p>\n        )}\n        {projectPeople.length > 0 && (\n          <ul className=\"mt-3 divide-y divide-line rounded-xl border border-line\">\n            {projectPeople.map((u) => (\n              <li key={u.key} className=\"flex flex-wrap items-center justify-between gap-2 px-4 py-2.5\">\n                <div className=\"min-w-0\">\n                  <p className=\"truncate text-sm font-bold\">{u.name || u.email}</p>\n                  <p className=\"truncate text-xs text-ink/50\">{u.email}</p>\n                </div>\n                <Badge tone=\"dark\">{u.roleName || roleName(u.roleCode)}</Badge>\n              </li>\n            ))}\n          </ul>\n        )}\n      </div>\n\n      {notice && <Alert tone=\"success\">{notice}</Alert>}\n      <Alert>{teams.error && errorText(teams.error)}</Alert>\n\n      {teams.loading ? (\n        <div className=\"py-12 text-center\">\n          <Spinner className=\"mx-auto h-6 w-6 text-brand\" />\n        </div>\n      ) : list.length === 0 ? (\n        <div className=\"rounded-2xl border border-dashed border-ink/20 bg-white/60 p-10 text-center\">\n          <p className=\"text-lg font-extrabold\">No teams yet</p>\n          <p className=\"mt-1 text-sm text-ink/60\">Create a team (for example Camera or Art), then add its members.</p>\n          {canManage && (\n            <Button className=\"mt-4\" onClick={() => setModal({ type: \"create\" })}>\n              + New team\n            </Button>\n          )}\n        </div>\n      ) : (\n        <div className=\"space-y-3\">\n          {list.map((t) => (\n            <TeamCard\n              key={t.id}\n              team={t}\n              open={isOpen(t.id)}\n              onToggle={() => toggle(t.id)}\n              canManage={canManage}\n              onEdit={() => setModal({ type: \"edit\", row: t })}\n              onDelete={() => removeTeam(t)}\n              orgId={orgId}\n              projectId={projectId}\n              canUser={canUser}\n            />\n          ))}\n        </div>\n      )}\n\n      {modal?.type === \"project\" && project && (\n        <FormModal\n          title=\"Edit project\"\n          fields={PROJECT_FIELDS}\n          initial={{\n            name: project.name,\n            project_type: project.project_type,\n            status: project.status,\n            start_date: project.start_date || \"\",\n            end_date: project.end_date || \"\",\n          }}\n          onSubmit={async (v) => {\n            await houses.updateProject(project.id, projectToBody(v));\n            setModal(null);\n            setNotice(\"Project saved\");\n            await houseQ.reload();\n          }}\n          onClose={() => setModal(null)}\n        />\n      )}\n      {modal?.type === \"create\" && (\n        <FormModal\n          title=\"New team\"\n          submitLabel=\"Create\"\n          fields={fields}\n          onSubmit={async (v) => {\n            await houses.createTeam(projectId, toBody(v));\n            await finish(\"Team created\");\n          }}\n          onClose={() => setModal(null)}\n        />\n      )}\n      {modal?.type === \"edit\" && (\n        <FormModal\n          title=\"Edit team\"\n          fields={fields}\n          initial={{\n            name: modal.row.name,\n            headcount: modal.row.headcount ?? \"\",\n            budget: rupees(modal.row.budget_paise),\n            advance: rupees(modal.row.advance_paise),\n          }}\n          onSubmit={async (v) => {\n            await houses.updateTeam(modal.row.id, toBody(v));\n            await finish(\"Team saved\");\n          }}\n          onClose={() => setModal(null)}\n        />\n      )}\n      {showUser && (\n        <CreateUserModal\n          presetOrgId={orgId}\n          presetProjectId={projectId}\n          onClose={() => setShowUser(false)}\n          onCreated={({ email, password }) => {\n            setShowUser(false);\n            setSecret({ title: \"User created\", email, password });\n            people.reload();\n          }}\n        />\n      )}\n      {secret && <PasswordModal {...secret} onClose={() => setSecret(null)} />}\n    </div>\n  );\n}\n",
 "src/pages/HousesPage.jsx": "import { useState } from \"react\";\nimport { Link } from \"react-router-dom\";\nimport * as houses from \"../api/houses\";\nimport { useAuth } from \"../features/auth/AuthContext.jsx\";\nimport { useLoad } from \"../lib/useLoad.js\";\nimport { Alert, Badge, Button, Spinner } from \"../components/ui.jsx\";\nimport { ActionBtn } from \"../components/Table.jsx\";\nimport FormModal from \"../components/FormModal.jsx\";\nimport { errorText } from \"../lib/errors.js\";\nimport { useConfirm } from \"../components/Confirm.jsx\";\n\nconst TYPES = { movie: \"Movie\", ott_series: \"OTT series\", ad: \"Ad\", other: \"Other\" };\nconst STATUSES = { draft: \"Draft\", planning: \"Planning\", active: \"Active\", wrapped: \"Wrapped\", closed: \"Closed\" };\nconst fmtDate = (s) =>\n  s ? new Date(s).toLocaleDateString(\"en-IN\", { day: \"2-digit\", month: \"short\", year: \"numeric\" }) : \"—\";\n\nexport default function HousesPage() {\n  const { can } = useAuth();\n  const confirm = useConfirm();\n  const [q, setQ] = useState(\"\");\n  // Each house comes with its projects inside, so everything shows on this one page.\n  const { data, loading, error, setError, reload } = useLoad(() => houses.listHouses(), []);\n  const [modal, setModal] = useState(null); // { type: \"create\" | \"rename\" | \"suspend\", row? }\n  const [notice, setNotice] = useState(\"\");\n\n  const needle = q.trim().toLowerCase();\n  const visibleHouses = needle\n    ? data.filter(\n        (h) => h.name.toLowerCase().includes(needle) || (h.projects || []).some((p) => p.name.toLowerCase().includes(needle))\n      )\n    : data;\n\n  async function finish(message) {\n    setModal(null);\n    setNotice(message);\n    await reload();\n  }\n\n  async function unsuspend(h) {\n    setNotice(\"\");\n    try {\n      await houses.updateHouse(h.id, { is_suspended: false, suspended_reason: \"\" });\n      await finish(`${h.name} is active again`);\n    } catch (e) {\n      setError(e);\n    }\n  }\n\n  async function remove(h) {\n    const ok = await confirm({\n      title: `Delete ${h.name}?`,\n      message: \"This only works if it has no projects and no users.\",\n      confirmLabel: \"Delete\",\n    });\n    if (!ok) return;\n    setNotice(\"\");\n    try {\n      await houses.deleteHouse(h.id);\n      await finish(`Deleted ${h.name}`);\n    } catch (e) {\n      setError(e); // the server explains what is blocking the delete\n    }\n  }\n\n  return (\n    <div className=\"space-y-6\">\n      <div className=\"flex flex-wrap items-end justify-between gap-4\">\n        <div>\n          <p className=\"text-sm font-bold uppercase tracking-widest text-brand\">Platform</p>\n          <h1 className=\"mt-1 text-4xl font-black tracking-tight\">Houses</h1>\n        </div>\n        {can(\"house.create\") && <Button onClick={() => setModal({ type: \"create\" })}>+ New house</Button>}\n      </div>\n\n      {notice && <Alert tone=\"success\">{notice}</Alert>}\n      <Alert>{error && errorText(error)}</Alert>\n\n      <input\n        className=\"input sm:max-w-sm\"\n        placeholder=\"Search houses or projects…\"\n        value={q}\n        onChange={(e) => setQ(e.target.value)}\n      />\n\n      {loading ? (\n        <div className=\"py-12 text-center\">\n          <Spinner className=\"mx-auto h-6 w-6 text-brand\" />\n        </div>\n      ) : visibleHouses.length === 0 ? (\n        <div className=\"rounded-2xl border border-dashed border-ink/20 bg-white/60 p-10 text-center text-sm text-ink/60\">\n          {q ? \"Nothing matches your search.\" : \"No houses found.\"}\n        </div>\n      ) : (\n        <div className=\"space-y-4\">\n          {visibleHouses.map((h) => {\n            const projects = h.projects || [];\n            return (\n              <div key={h.id} className=\"overflow-hidden rounded-2xl border border-line bg-white\">\n                {/* House header */}\n                <div className=\"flex flex-wrap items-center justify-between gap-3 px-5 py-4\">\n                  <div className=\"min-w-0\">\n                    <Link\n                      to={`/houses/${h.id}`}\n                      state={{ name: h.name }}\n                      className=\"text-xl font-extrabold tracking-tight hover:text-brand\"\n                    >\n                      {h.name}\n                    </Link>\n                    <p className=\"mt-0.5 flex flex-wrap items-center gap-2 text-xs text-ink/55\">\n                      {h.is_suspended ? (\n                        <>\n                          <Badge tone=\"red\">Suspended</Badge>\n                          {h.suspended_reason && <span>{h.suspended_reason}</span>}\n                        </>\n                      ) : (\n                        <Badge tone=\"dark\">Active</Badge>\n                      )}\n                      <span>\n                        {projects.length} {projects.length === 1 ? \"project\" : \"projects\"}\n                      </span>\n                    </p>\n                  </div>\n                  <div className=\"flex flex-wrap gap-1\">\n                    <Link\n                      to={`/houses/${h.id}`}\n                      state={{ name: h.name }}\n                      className=\"rounded-md px-2 py-1 text-xs font-semibold text-brand hover:bg-brand-light\"\n                    >\n                      Open house →\n                    </Link>\n                    {can(\"house.create\") && <ActionBtn onClick={() => setModal({ type: \"rename\", row: h })}>Rename</ActionBtn>}\n                    {can(\"house.suspend\") &&\n                      (h.is_suspended ? (\n                        <ActionBtn onClick={() => unsuspend(h)}>Unsuspend</ActionBtn>\n                      ) : (\n                        <ActionBtn onClick={() => setModal({ type: \"suspend\", row: h })}>Suspend</ActionBtn>\n                      ))}\n                    {can(\"house.create\") && (\n                      <ActionBtn danger onClick={() => remove(h)}>\n                        Delete\n                      </ActionBtn>\n                    )}\n                  </div>\n                </div>\n\n                {/* Projects, shown right here */}\n                <div className=\"border-t border-line bg-mist/60 p-4\">\n                  {projects.length === 0 ? (\n                    <p className=\"text-sm text-ink/55\">\n                      No projects yet.{\" \"}\n                      <Link to={`/houses/${h.id}`} state={{ name: h.name }} className=\"font-semibold text-brand hover:underline\">\n                        Create the first project →\n                      </Link>\n                    </p>\n                  ) : (\n                    <div className=\"grid gap-3 sm:grid-cols-2 lg:grid-cols-3\">\n                      {projects.map((p) => (\n                        <Link\n                          key={p.id}\n                          to={`/projects/${p.id}`}\n                          state={{ name: p.name, orgId: h.id, houseName: h.name }}\n                          className=\"rounded-xl border border-line bg-white p-4 transition hover:-translate-y-0.5 hover:border-brand hover:shadow-md\"\n                        >\n                          <div className=\"flex items-center justify-between gap-2\">\n                            <Badge tone={p.status === \"active\" ? \"dark\" : \"neutral\"}>{STATUSES[p.status] || p.status}</Badge>\n                            <span className=\"text-xs font-semibold text-ink/50\">{TYPES[p.project_type] || p.project_type}</span>\n                          </div>\n                          <p className=\"mt-2 font-extrabold\">{p.name}</p>\n                          <p className=\"mt-0.5 text-xs text-ink/55\">\n                            {fmtDate(p.start_date)} → {fmtDate(p.end_date)}\n                          </p>\n                        </Link>\n                      ))}\n                    </div>\n                  )}\n                </div>\n              </div>\n            );\n          })}\n        </div>\n      )}\n\n      {modal?.type === \"create\" && (\n        <FormModal\n          title=\"New house\"\n          submitLabel=\"Create\"\n          fields={[{ name: \"name\", label: \"House name\", required: true }]}\n          onSubmit={async (v) => {\n            await houses.createHouse(v.name.trim());\n            await finish(\"House created\");\n          }}\n          onClose={() => setModal(null)}\n        />\n      )}\n      {modal?.type === \"rename\" && (\n        <FormModal\n          title=\"Rename house\"\n          fields={[{ name: \"name\", label: \"House name\", required: true }]}\n          initial={{ name: modal.row.name }}\n          onSubmit={async (v) => {\n            await houses.updateHouse(modal.row.id, { name: v.name.trim() });\n            await finish(\"House renamed\");\n          }}\n          onClose={() => setModal(null)}\n        />\n      )}\n      {modal?.type === \"suspend\" && (\n        <FormModal\n          title={`Suspend ${modal.row.name}`}\n          submitLabel=\"Suspend\"\n          fields={[{ name: \"reason\", label: \"Reason\", required: true, hint: \"Shown to admins, for example: Payment pending\" }]}\n          onSubmit={async (v) => {\n            await houses.updateHouse(modal.row.id, { is_suspended: true, suspended_reason: v.reason.trim() });\n            await finish(`${modal.row.name} suspended`);\n          }}\n          onClose={() => setModal(null)}\n        />\n      )}\n    </div>\n  );\n}\n",
 "src/pages/HouseDetailPage.jsx": "import { useState } from \"react\";\nimport { Link, useLocation, useParams } from \"react-router-dom\";\nimport * as houses from \"../api/houses\";\nimport * as usersApi from \"../api/users\";\nimport { useAuth } from \"../features/auth/AuthContext.jsx\";\nimport CreateUserModal from \"../features/users/CreateUserModal.jsx\";\nimport PasswordModal from \"../features/users/PasswordModal.jsx\";\nimport { useLoad } from \"../lib/useLoad.js\";\nimport { Alert, Badge, Button, Spinner } from \"../components/ui.jsx\";\nimport { ActionBtn } from \"../components/Table.jsx\";\nimport FormModal from \"../components/FormModal.jsx\";\nimport { errorText } from \"../lib/errors.js\";\nimport { roleName } from \"../lib/roles.js\";\nimport { useConfirm } from \"../components/Confirm.jsx\";\n\nconst TYPES = [\n  { value: \"movie\", label: \"Movie\" },\n  { value: \"ott_series\", label: \"OTT series\" },\n  { value: \"ad\", label: \"Ad\" },\n  { value: \"other\", label: \"Other\" },\n];\nconst STATUSES = [\n  { value: \"draft\", label: \"Draft\" },\n  { value: \"planning\", label: \"Planning\" },\n  { value: \"active\", label: \"Active\" },\n  { value: \"wrapped\", label: \"Wrapped\" },\n  { value: \"closed\", label: \"Closed\" },\n];\nconst label = (list, value) => list.find((x) => x.value === value)?.label || value || \"—\";\nconst fmtDate = (s) =>\n  s ? new Date(s).toLocaleDateString(\"en-IN\", { day: \"2-digit\", month: \"short\", year: \"numeric\" }) : \"—\";\n\nconst FIELDS = [\n  { name: \"name\", label: \"Project name\", required: true },\n  { name: \"project_type\", label: \"Type\", as: \"select\", options: TYPES, required: true },\n  { name: \"status\", label: \"Status\", as: \"select\", options: STATUSES },\n  { name: \"start_date\", label: \"Start date\", type: \"date\" },\n  { name: \"end_date\", label: \"End date\", type: \"date\" },\n];\n\nfunction toBody(v) {\n  const body = { name: v.name.trim(), project_type: v.project_type };\n  if (v.status) body.status = v.status;\n  if (v.start_date) body.start_date = v.start_date;\n  if (v.end_date) body.end_date = v.end_date;\n  return body;\n}\n\nexport default function HouseDetailPage() {\n  const { orgId } = useParams();\n  const stateName = useLocation().state?.name;\n  const { can } = useAuth();\n  const confirm = useConfirm();\n  const [tab, setTab] = useState(\"projects\");\n  const [modal, setModal] = useState(null); // { type: \"create\" | \"edit\", row? }\n  const [showUser, setShowUser] = useState(false);\n  const [secret, setSecret] = useState(null);\n  const [notice, setNotice] = useState(\"\");\n\n  // The houses list already includes each house's projects, so one call is enough\n  const houseQ = useLoad(() => houses.listHouses(), []);\n  const house = houseQ.data.find((h) => String(h.id) === String(orgId));\n  const houseName = house?.name || stateName || `House #${orgId}`;\n  const projects = {\n    data: house?.projects || [],\n    loading: houseQ.loading,\n    error: houseQ.error,\n    setError: houseQ.setError,\n    reload: houseQ.reload,\n  };\n  const people = useLoad(\n    async () =>\n      usersApi\n        .normalizeUsers(await usersApi.listUsers({ organisation_id: orgId }))\n        .filter((u) => String(u.orgId) === String(orgId)),\n    [orgId]\n  );\n\n  const canProject = can(\"project.create\");\n  const canUser = can(\"users.create.user\") || can(\"users.create.admin\");\n\n  async function finish(message) {\n    setModal(null);\n    setNotice(message);\n    await projects.reload();\n  }\n\n  async function removeProject(p) {\n    const ok = await confirm({\n      title: `Delete ${p.name}?`,\n      message: \"This only works if it has no teams or expenses.\",\n      confirmLabel: \"Delete\",\n    });\n    if (!ok) return;\n    setNotice(\"\");\n    try {\n      await houses.deleteProject(p.id);\n      await finish(`Deleted ${p.name}`);\n    } catch (e) {\n      projects.setError(e);\n    }\n  }\n\n  const hasPeople = people.data.length > 0;\n  const hasProjects = projects.data.length > 0;\n\n  return (\n    <div className=\"space-y-6\">\n      <div>\n        <p className=\"text-sm font-semibold text-ink/55\">\n          <Link to=\"/houses\" className=\"hover:text-brand\">Houses</Link> / {houseName}\n        </p>\n        <h1 className=\"mt-1 text-4xl font-black tracking-tight\">{houseName}</h1>\n      </div>\n\n      {/* Tabs */}\n      <div className=\"flex gap-1 border-b border-line\">\n        {[\n          { id: \"projects\", label: `Projects${hasProjects ? ` (${projects.data.length})` : \"\"}` },\n          { id: \"people\", label: `People${hasPeople ? ` (${people.data.length})` : \"\"}` },\n        ].map((t) => (\n          <button\n            key={t.id}\n            onClick={() => setTab(t.id)}\n            className={`-mb-px cursor-pointer border-b-2 px-4 py-2.5 text-sm font-bold transition ${\n              tab === t.id ? \"border-brand text-brand\" : \"border-transparent text-ink/55 hover:text-ink\"\n            }`}\n          >\n            {t.label}\n          </button>\n        ))}\n      </div>\n\n      {notice && <Alert tone=\"success\">{notice}</Alert>}\n\n      {/* PROJECTS TAB */}\n      {tab === \"projects\" && (\n        <div className=\"space-y-4\">\n          <div className=\"flex justify-end\">\n            {canProject && <Button onClick={() => setModal({ type: \"create\" })}>+ New project</Button>}\n          </div>\n          <Alert>{projects.error && errorText(projects.error)}</Alert>\n          {projects.loading ? (\n            <div className=\"py-10 text-center\">\n              <Spinner className=\"mx-auto h-6 w-6 text-brand\" />\n            </div>\n          ) : !hasProjects ? (\n            <div className=\"rounded-2xl border border-dashed border-ink/20 bg-white/60 p-10 text-center text-sm text-ink/60\">\n              No projects yet.\n            </div>\n          ) : (\n            <div className=\"grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n              {projects.data.map((p) => (\n                <div\n                  key={p.id}\n                  className=\"group relative rounded-2xl border border-line bg-white p-5 transition hover:-translate-y-0.5 hover:border-brand hover:shadow-lg\"\n                >\n                  {/* The whole card opens the project */}\n                  <Link\n                    to={`/projects/${p.id}`}\n                    state={{ name: p.name, orgId, houseName }}\n                    aria-label={`Open ${p.name}`}\n                    className=\"absolute inset-0 rounded-2xl\"\n                  />\n                  <div className=\"flex items-start justify-between gap-2\">\n                    <Badge tone={p.status === \"active\" ? \"dark\" : \"neutral\"}>{label(STATUSES, p.status)}</Badge>\n                    <span className=\"text-xs font-semibold text-ink/50\">{label(TYPES, p.project_type)}</span>\n                  </div>\n                  <h3 className=\"mt-3 text-xl font-extrabold tracking-tight\">{p.name}</h3>\n                  <p className=\"mt-1 text-xs text-ink/55\">\n                    {fmtDate(p.start_date)} → {fmtDate(p.end_date)}\n                  </p>\n                  <div className=\"relative z-10 mt-4 flex items-center justify-between\">\n                    <span className=\"text-sm font-bold text-brand\">Open teams →</span>\n                    {canProject && (\n                      <div className=\"flex\">\n                        <ActionBtn onClick={() => setModal({ type: \"edit\", row: p })}>Edit</ActionBtn>\n                        <ActionBtn danger onClick={() => removeProject(p)}>\n                          Delete\n                        </ActionBtn>\n                      </div>\n                    )}\n                  </div>\n                </div>\n              ))}\n            </div>\n          )}\n        </div>\n      )}\n\n      {/* PEOPLE TAB */}\n      {tab === \"people\" && (\n        <div className=\"space-y-4\">\n          <div className=\"flex flex-wrap items-center justify-between gap-2\">\n            <p className=\"text-sm text-ink/60\">Everyone who can log in to this house.</p>\n            <div className=\"flex gap-2\">\n              <Link to=\"/users\" className=\"inline-flex items-center rounded-lg px-3 text-sm font-semibold text-brand hover:bg-brand-light\">\n                Manage all users →\n              </Link>\n              {canUser && <Button onClick={() => setShowUser(true)}>+ Add user</Button>}\n            </div>\n          </div>\n          <Alert>{people.error && errorText(people.error)}</Alert>\n          {people.loading ? (\n            <div className=\"py-10 text-center\">\n              <Spinner className=\"mx-auto h-6 w-6 text-brand\" />\n            </div>\n          ) : !hasPeople ? (\n            <div className=\"rounded-2xl border border-dashed border-ink/20 bg-white/60 p-10 text-center text-sm text-ink/60\">\n              No users in this house yet. Add the Producer first.\n            </div>\n          ) : (\n            <ul className=\"divide-y divide-line overflow-hidden rounded-2xl border border-line bg-white\">\n              {people.data.map((u) => (\n                <li key={u.key} className=\"flex flex-wrap items-center justify-between gap-2 px-5 py-3\">\n                  <div className=\"min-w-0\">\n                    <p className=\"truncate font-bold\">{u.name || u.email}</p>\n                    <p className=\"truncate text-xs text-ink/50\">{u.email}</p>\n                  </div>\n                  <div className=\"flex items-center gap-2\">\n                    <Badge tone=\"dark\">{u.roleName || roleName(u.roleCode)}</Badge>\n                    <Badge tone=\"neutral\">{u.projectName || \"Whole house\"}</Badge>\n                    {!u.active && <Badge>Inactive</Badge>}\n                  </div>\n                </li>\n              ))}\n            </ul>\n          )}\n        </div>\n      )}\n\n      {/* Popups */}\n      {modal?.type === \"create\" && (\n        <FormModal\n          title=\"New project\"\n          submitLabel=\"Create\"\n          fields={FIELDS}\n          initial={{ project_type: \"movie\", status: \"draft\" }}\n          onSubmit={async (v) => {\n            await houses.createProject(orgId, toBody(v));\n            await finish(\"Project created\");\n          }}\n          onClose={() => setModal(null)}\n        />\n      )}\n      {modal?.type === \"edit\" && (\n        <FormModal\n          title=\"Edit project\"\n          fields={FIELDS}\n          initial={{\n            name: modal.row.name,\n            project_type: modal.row.project_type,\n            status: modal.row.status,\n            start_date: modal.row.start_date || \"\",\n            end_date: modal.row.end_date || \"\",\n          }}\n          onSubmit={async (v) => {\n            await houses.updateProject(modal.row.id, toBody(v));\n            await finish(\"Project saved\");\n          }}\n          onClose={() => setModal(null)}\n        />\n      )}\n      {showUser && (\n        <CreateUserModal\n          presetOrgId={orgId}\n          onClose={() => setShowUser(false)}\n          onCreated={({ email, password }) => {\n            setShowUser(false);\n            setSecret({ title: \"User created\", email, password });\n            people.reload();\n          }}\n        />\n      )}\n      {secret && <PasswordModal {...secret} onClose={() => setSecret(null)} />}\n    </div>\n  );\n}\n",
 "src/features/users/CreateUserModal.jsx": "import { useEffect, useState } from \"react\";\nimport * as usersApi from \"../../api/users\";\nimport * as houses from \"../../api/houses\";\nimport { useAuth } from \"../auth/AuthContext.jsx\";\nimport { Alert, Button, Field, Modal } from \"../../components/ui.jsx\";\nimport { errorText, fieldError } from \"../../lib/errors.js\";\nimport { ROLES, isPlatformRole } from \"../../lib/roles.js\";\nimport PermissionPicker from \"./PermissionPicker.jsx\";\n\nconst hasLogin = (m) => Boolean(m.has_login || m.user_id || m.user);\n\nexport default function CreateUserModal({\n  onClose,\n  onCreated,\n  presetOrgId,\n  presetProjectId,\n  presetTeamId,\n  presetMemberId,\n  presetRole,\n  presetName,\n}) {\n  const { can } = useAuth();\n  const [form, setForm] = useState({\n    email: \"\",\n    full_name: presetName || \"\",\n    role_code: presetRole || \"producer\",\n    organisation_id: presetOrgId ? String(presetOrgId) : \"\",\n    project_id: presetProjectId ? String(presetProjectId) : \"\",\n    team_ids: \"\",\n    team_id: presetTeamId ? String(presetTeamId) : \"\",\n    member_id: presetMemberId ? String(presetMemberId) : \"\",\n  });\n  const [orgs, setOrgs] = useState([]);\n  const [teams, setTeams] = useState([]);\n  const [members, setMembers] = useState([]);\n  const [extra, setExtra] = useState({});\n  const [showPerms, setShowPerms] = useState(false);\n  const [error, setError] = useState(null);\n  const [busy, setBusy] = useState(false);\n\n  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));\n  const platform = isPlatformRole(form.role_code);\n  const teamHead = form.role_code === \"team_head\";\n\n  // Only offer roles this person may create. (Super Admin accounts are not created here.)\n  const allRoles = ROLES.filter((r) => r.code !== \"super_admin\" && (r.code !== \"admin\" || can(\"users.create.admin\")));\n  // Inside a house, only house roles make sense\n  const baseRoles = presetOrgId ? allRoles.filter((r) => !isPlatformRole(r.code)) : allRoles;\n  const roles = presetRole ? baseRoles.filter((r) => r.code === presetRole) : baseRoles;\n\n  useEffect(() => {\n    usersApi\n      .listOrganisations()\n      .then((d) => setOrgs(Array.isArray(d) ? d : d?.results || []))\n      .catch(() => setOrgs([]));\n  }, []);\n\n  const selectedOrg = orgs.find((o) => String(o.id) === String(form.organisation_id));\n  const projects = selectedOrg?.projects || [];\n\n  // Team Head: teams of the chosen project\n  useEffect(() => {\n    if (!teamHead || !form.project_id) {\n      setTeams([]);\n      return;\n    }\n    houses\n      .listTeams(form.project_id)\n      .then((d) => setTeams(houses.asList(d)))\n      .catch(() => setTeams([]));\n  }, [teamHead, form.project_id]);\n\n  // Team Head: members of the chosen team\n  useEffect(() => {\n    if (!teamHead || !form.team_id) {\n      setMembers([]);\n      return;\n    }\n    houses\n      .listMembers(form.team_id)\n      .then((d) => setMembers(houses.asList(d)))\n      .catch(() => setMembers([]));\n  }, [teamHead, form.team_id]);\n\n  function changeHouse(e) {\n    setForm((f) => ({ ...f, organisation_id: e.target.value, project_id: \"\", team_id: \"\", member_id: \"\" }));\n  }\n  function changeProject(e) {\n    setForm((f) => ({ ...f, project_id: e.target.value, team_id: \"\", member_id: \"\" }));\n  }\n  function changeTeam(e) {\n    setForm((f) => ({ ...f, team_id: e.target.value, member_id: \"\" }));\n  }\n  function changeMember(e) {\n    const id = e.target.value;\n    const m = members.find((x) => String(x.id) === id);\n    setForm((f) => ({ ...f, member_id: id, full_name: m && !f.full_name ? m.name : f.full_name }));\n  }\n\n  async function submit(e) {\n    e.preventDefault();\n    setBusy(true);\n    setError(null);\n    try {\n      const body = { email: form.email.trim(), role_code: form.role_code };\n      if (form.full_name.trim()) body.full_name = form.full_name.trim();\n      if (!platform) {\n        // Platform roles take NO organisation. House roles need one.\n        body.organisation_id = Number(form.organisation_id);\n        if (form.project_id) body.project_id = Number(form.project_id);\n        if (teamHead) {\n          if (form.team_id) body.team_ids = [Number(form.team_id)];\n          if (form.member_id) body.team_member_id = Number(form.member_id);\n        } else {\n          const ids = form.team_ids\n            .split(\",\")\n            .map((s) => s.trim())\n            .filter(Boolean)\n            .map(Number);\n          if (ids.length) body.team_ids = ids;\n        }\n      }\n      const extraList = Object.entries(extra).map(([code, effect]) => ({ code, effect }));\n      if (extraList.length) body.extra_permissions = extraList;\n\n      const res = await usersApi.createUser(body);\n      onCreated({ email: body.email, password: res.generated_password });\n    } catch (err) {\n      setError(err);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  const projectHint = !form.organisation_id\n    ? \"Choose a house first\"\n    : projects.length === 0\n      ? \"This house has no projects yet\"\n      : teamHead\n        ? \"A Team Head belongs to one project\"\n        : form.project_id\n          ? \"This person will only see this project\"\n          : \"Leave empty and this person gets the whole house (every project)\";\n\n  return (\n    <Modal title={teamHead ? \"New Team Head login\" : \"New user\"} onClose={onClose} wide>\n      <form onSubmit={submit} className=\"space-y-4\">\n        <Alert>{error && errorText(error)}</Alert>\n\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <Field label=\"Email\" type=\"email\" required value={form.email} onChange={set(\"email\")} error={fieldError(error, \"email\")} />\n          <Field label=\"Full name\" value={form.full_name} onChange={set(\"full_name\")} error={fieldError(error, \"full_name\")} />\n        </div>\n\n        <Field\n          label=\"Role\"\n          as=\"select\"\n          value={form.role_code}\n          onChange={set(\"role_code\")}\n          disabled={Boolean(presetRole)}\n          error={fieldError(error, \"role_code\")}\n        >\n          {roles.map((r) => (\n            <option key={r.code} value={r.code}>\n              {r.name}\n            </option>\n          ))}\n        </Field>\n\n        {!platform && (\n          <>\n            <div className=\"grid gap-4 sm:grid-cols-2\">\n              <Field\n                label=\"House\"\n                as=\"select\"\n                required\n                disabled={Boolean(presetOrgId)}\n                value={form.organisation_id}\n                onChange={changeHouse}\n                error={fieldError(error, \"organisation_id\")}\n              >\n                <option value=\"\">Select a house…</option>\n                {orgs.map((o) => (\n                  <option key={o.id} value={o.id}>\n                    {o.name}\n                  </option>\n                ))}\n              </Field>\n\n              <Field\n                label=\"Project\"\n                as=\"select\"\n                required={teamHead}\n                disabled={Boolean(presetProjectId) || !form.organisation_id}\n                value={form.project_id}\n                onChange={changeProject}\n                error={fieldError(error, \"project_id\")}\n                hint={projectHint}\n              >\n                <option value=\"\">{teamHead ? \"Select a project…\" : \"Whole house (all projects)\"}</option>\n                {projects.map((p) => (\n                  <option key={p.id} value={p.id}>\n                    {p.name}\n                  </option>\n                ))}\n              </Field>\n            </div>\n\n            {teamHead ? (\n              <div className=\"grid gap-4 sm:grid-cols-2\">\n                <Field\n                  label=\"Team\"\n                  as=\"select\"\n                  required\n                  disabled={Boolean(presetTeamId) || !form.project_id}\n                  value={form.team_id}\n                  onChange={changeTeam}\n                  error={fieldError(error, \"team_ids\")}\n                  hint={form.project_id && teams.length === 0 ? \"This project has no teams yet\" : undefined}\n                >\n                  <option value=\"\">Select a team…</option>\n                  {teams.map((t) => (\n                    <option key={t.id} value={t.id}>\n                      {t.name}\n                    </option>\n                  ))}\n                </Field>\n                <Field\n                  label=\"Team member\"\n                  as=\"select\"\n                  required\n                  disabled={Boolean(presetMemberId) || !form.team_id}\n                  value={form.member_id}\n                  onChange={changeMember}\n                  error={fieldError(error, \"team_member_id\")}\n                  hint=\"The person in the team who will log in\"\n                >\n                  <option value=\"\">Select a member…</option>\n                  {members.map((m) => (\n                    <option key={m.id} value={m.id} disabled={hasLogin(m)}>\n                      {m.name}\n                      {m.is_team_head ? \" (Team Head)\" : \"\"}\n                      {hasLogin(m) ? \" — already has a login\" : \"\"}\n                    </option>\n                  ))}\n                </Field>\n              </div>\n            ) : (\n              <Field\n                label=\"Team IDs\"\n                value={form.team_ids}\n                onChange={set(\"team_ids\")}\n                error={fieldError(error, \"team_ids\")}\n                hint=\"Optional, for example 1,2\"\n              />\n            )}\n          </>\n        )}\n\n        <div>\n          <button\n            type=\"button\"\n            onClick={() => setShowPerms(!showPerms)}\n            className=\"cursor-pointer text-sm font-semibold text-brand hover:underline\"\n          >\n            {showPerms\n              ? \"− Hide extra permissions\"\n              : `+ Extra permissions (optional)${Object.keys(extra).length ? ` · ${Object.keys(extra).length} set` : \"\"}`}\n          </button>\n          {showPerms && (\n            <div className=\"mt-3\">\n              <p className=\"mb-3 text-sm text-ink/60\">\n                \"Allow\" adds a permission the role does not normally have. \"Deny\" removes one it does have. Leave on Default\n                to use the role as it is.\n              </p>\n              <PermissionPicker value={extra} onChange={setExtra} roleCode={form.role_code} />\n            </div>\n          )}\n        </div>\n\n        <div className=\"flex gap-3 pt-2\">\n          <Button type=\"button\" variant=\"outline\" onClick={onClose} className=\"flex-1\">\n            Cancel\n          </Button>\n          <Button type=\"submit\" loading={busy} className=\"flex-1\">\n            Create user\n          </Button>\n        </div>\n      </form>\n    </Modal>\n  );\n}\n",
 "src/features/users/EditUserModal.jsx": "import { useState } from \"react\";\nimport * as usersApi from \"../../api/users\";\nimport { Alert, Button, Field, Modal } from \"../../components/ui.jsx\";\nimport { errorText, fieldError } from \"../../lib/errors.js\";\nimport { ROLES, isPlatformRole } from \"../../lib/roles.js\";\n\n/** Edit one person's name and email, and this role (hat): its type and whether it is switched on. */\nexport default function EditUserModal({ target, onClose, onSaved }) {\n  const [form, setForm] = useState({\n    full_name: target.name || \"\",\n    email: target.email || \"\",\n    role_code: target.roleCode || \"\",\n    role_active: target.profileActive !== false,\n  });\n  const [error, setError] = useState(null);\n  const [busy, setBusy] = useState(false);\n  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));\n\n  // Only roles of the same kind (platform / house) make sense here\n  const sameKind = ROLES.filter((r) => r.code !== \"super_admin\" && isPlatformRole(r.code) === isPlatformRole(target.roleCode));\n\n  async function submit(e) {\n    e.preventDefault();\n    setBusy(true);\n    setError(null);\n    try {\n      const person = {};\n      if (form.full_name.trim() !== (target.name || \"\")) person.full_name = form.full_name.trim();\n      if (form.email.trim() !== (target.email || \"\")) person.email = form.email.trim();\n      if (Object.keys(person).length) await usersApi.updateUser(target.userId, person);\n\n      if (target.profileId) {\n        const profile = {};\n        if (form.role_code && form.role_code !== target.roleCode) profile.role_code = form.role_code;\n        if (form.role_active !== (target.profileActive !== false)) profile.is_active = form.role_active;\n        if (Object.keys(profile).length) await usersApi.updateProfile(target.profileId, profile);\n      }\n      onSaved();\n    } catch (err) {\n      setError(err);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <Modal title=\"Edit user\" onClose={onClose}>\n      <form onSubmit={submit} className=\"space-y-4\">\n        <Alert>{error && errorText(error)}</Alert>\n        <Field label=\"Full name\" value={form.full_name} onChange={set(\"full_name\")} error={fieldError(error, \"full_name\")} />\n        <Field label=\"Email\" type=\"email\" required value={form.email} onChange={set(\"email\")} error={fieldError(error, \"email\")} />\n        {target.profileId && (\n          <>\n            <Field label=\"Role\" as=\"select\" value={form.role_code} onChange={set(\"role_code\")} error={fieldError(error, \"role_code\")}>\n              {sameKind.map((r) => (\n                <option key={r.code} value={r.code}>\n                  {r.name}\n                </option>\n              ))}\n            </Field>\n            <label className=\"flex cursor-pointer items-start gap-2 text-sm font-semibold\">\n              <input\n                type=\"checkbox\"\n                checked={form.role_active}\n                onChange={(e) => setForm((f) => ({ ...f, role_active: e.target.checked }))}\n                className=\"mt-0.5 h-4 w-4 accent-brand\"\n              />\n              <span>\n                This role is active\n                <span className=\"block text-xs font-normal text-ink/55\">\n                  Switch off to stop only this role. The person's other roles keep working.\n                </span>\n              </span>\n            </label>\n          </>\n        )}\n        <div className=\"flex gap-3 pt-2\">\n          <Button type=\"button\" variant=\"outline\" onClick={onClose} className=\"flex-1\">\n            Cancel\n          </Button>\n          <Button type=\"submit\" loading={busy} className=\"flex-1\">\n            Save\n          </Button>\n        </div>\n      </form>\n    </Modal>\n  );\n}\n",
 "src/features/projects/TeamCard.jsx": "import { useCallback, useEffect, useState } from \"react\";\nimport * as houses from \"../../api/houses\";\nimport { Alert, Badge, Button, Spinner } from \"../../components/ui.jsx\";\nimport { ActionBtn } from \"../../components/Table.jsx\";\nimport FormModal from \"../../components/FormModal.jsx\";\nimport { errorText } from \"../../lib/errors.js\";\nimport { formatPaise } from \"../../lib/money.js\";\nimport { useConfirm } from \"../../components/Confirm.jsx\";\nimport CreateUserModal from \"../users/CreateUserModal.jsx\";\nimport PasswordModal from \"../users/PasswordModal.jsx\";\n\nconst FIELDS = [\n  { name: \"name\", label: \"Full name\", required: true },\n  { name: \"phone\", label: \"Phone\", type: \"tel\" },\n  { name: \"job_title\", label: \"Job title\", hint: \"For example: Gaffer\" },\n  { name: \"is_team_head\", type: \"checkbox\", label: \"This person is the Team Head (only one per team)\" },\n];\n\nconst toBody = (v) => ({\n  name: v.name.trim(),\n  phone: v.phone.trim(),\n  job_title: v.job_title.trim(),\n  is_team_head: Boolean(v.is_team_head),\n});\n\n/** One team. Opens to show its members right here, so there is no extra page to click into. */\nexport default function TeamCard({ team, open, onToggle, canManage, onEdit, onDelete, orgId, projectId, canUser }) {\n  const confirm = useConfirm();\n  const [loginFor, setLoginFor] = useState(null); // member who gets a Team Head login\n  const [secret, setSecret] = useState(null);\n  const [members, setMembers] = useState(null); // null = not loaded yet\n  const [error, setError] = useState(null);\n  const [notice, setNotice] = useState(\"\");\n  const [modal, setModal] = useState(null); // { type: \"add\" | \"edit\", row? }\n\n  const load = useCallback(async () => {\n    try {\n      const d = await houses.listMembers(team.id);\n      setMembers(Array.isArray(d) ? d : d?.results || []);\n      setError(null);\n    } catch (e) {\n      setError(e);\n      setMembers([]);\n    }\n  }, [team.id]);\n\n  useEffect(() => {\n    if (open && members === null) load();\n  }, [open, members, load]);\n\n  async function finish(message) {\n    setModal(null);\n    setNotice(message);\n    await load();\n  }\n\n  async function setActive(m, active) {\n    setNotice(\"\");\n    try {\n      await houses.updateMember(m.id, { is_active: active });\n      await finish(`${m.name} ${active ? \"activated\" : \"deactivated\"}`);\n    } catch (e) {\n      setError(e);\n    }\n  }\n\n  async function remove(m) {\n    const ok = await confirm({\n      title: `Delete ${m.name}?`,\n      message: \"This only works if they have no pay rates. Otherwise deactivate them instead.\",\n      confirmLabel: \"Delete\",\n    });\n    if (!ok) return;\n    setNotice(\"\");\n    try {\n      await houses.deleteMember(m.id);\n      await finish(`Deleted ${m.name}`);\n    } catch (e) {\n      setError(e);\n    }\n  }\n\n  return (\n    <div className=\"overflow-hidden rounded-2xl border border-line bg-white\">\n      {/* Team header */}\n      <div className=\"flex flex-wrap items-center justify-between gap-3 px-5 py-4\">\n        <button onClick={onToggle} className=\"flex min-w-0 flex-1 cursor-pointer items-center gap-3 text-left\">\n          <span\n            className={`grid h-7 w-7 shrink-0 place-items-center rounded-full bg-brand-light text-xs text-brand transition ${\n              open ? \"rotate-90\" : \"\"\n            }`}\n          >\n            ▸\n          </span>\n          <span className=\"min-w-0\">\n            <span className=\"block truncate text-lg font-extrabold\">{team.name}</span>\n            <span className=\"block text-xs text-ink/55\">\n              {team.headcount ?? 0} people planned\n              {team.budget_paise != null && <> · Budget {formatPaise(team.budget_paise)}</>}\n              {team.advance_paise != null && <> · Advance {formatPaise(team.advance_paise)}</>}\n              {members && <> · {members.length} added</>}\n            </span>\n          </span>\n        </button>\n        {canManage && (\n          <div className=\"flex gap-1\">\n            <ActionBtn onClick={onEdit}>Edit team</ActionBtn>\n            <ActionBtn danger onClick={onDelete}>\n              Delete\n            </ActionBtn>\n          </div>\n        )}\n      </div>\n\n      {/* Members */}\n      {open && (\n        <div className=\"border-t border-line bg-mist/60 px-5 py-4\">\n          {notice && <Alert tone=\"success\" className=\"mb-3\">{notice}</Alert>}\n          <Alert className=\"mb-3\">{error && errorText(error)}</Alert>\n\n          {members === null ? (\n            <Spinner className=\"h-5 w-5 text-brand\" />\n          ) : (\n            <>\n              {members.length === 0 ? (\n                <p className=\"py-2 text-sm text-ink/55\">No members in this team yet.</p>\n              ) : (\n                <ul className=\"divide-y divide-line rounded-xl border border-line bg-white\">\n                  {members.map((m) => {\n                    const active = m.is_active ?? true;\n                    return (\n                      <li key={m.id} className=\"flex flex-wrap items-center justify-between gap-2 px-4 py-2.5\">\n                        <div className=\"min-w-0\">\n                          <p className=\"truncate text-sm font-bold\">\n                            {m.name}{\" \"}\n                            {m.is_team_head && <Badge tone=\"red\">Team Head</Badge>}{\" \"}\n                            {(m.has_login || m.user_id) && <Badge tone=\"dark\">Has login</Badge>}{\" \"}\n                            {!active && <Badge>Inactive</Badge>}\n                          </p>\n                          <p className=\"text-xs text-ink/50\">\n                            {[m.job_title, m.phone].filter(Boolean).join(\" · \") || \"No details\"}\n                          </p>\n                        </div>\n                        {(canManage || (canUser && m.is_team_head)) && (\n                          <div className=\"flex flex-wrap gap-1\">\n                            {canUser && orgId && m.is_team_head && !(m.has_login || m.user_id) && (\n                              <ActionBtn onClick={() => setLoginFor(m)}>Create login</ActionBtn>\n                            )}\n                            {canManage && (\n                              <>\n                            <ActionBtn onClick={() => setModal({ type: \"edit\", row: m })}>Edit</ActionBtn>\n                            <ActionBtn onClick={() => setActive(m, !active)}>{active ? \"Deactivate\" : \"Activate\"}</ActionBtn>\n                            <ActionBtn danger onClick={() => remove(m)}>\n                              Delete\n                            </ActionBtn>\n                              </>\n                            )}\n                          </div>\n                        )}\n                      </li>\n                    );\n                  })}\n                </ul>\n              )}\n              {canManage && (\n                <Button variant=\"outline\" className=\"mt-3 !py-2\" onClick={() => setModal({ type: \"add\" })}>\n                  + Add member\n                </Button>\n              )}\n            </>\n          )}\n        </div>\n      )}\n\n      {loginFor && (\n        <CreateUserModal\n          presetOrgId={orgId}\n          presetProjectId={projectId}\n          presetTeamId={team.id}\n          presetMemberId={loginFor.id}\n          presetRole=\"team_head\"\n          presetName={loginFor.name}\n          onClose={() => setLoginFor(null)}\n          onCreated={({ email, password }) => {\n            setLoginFor(null);\n            setSecret({ title: \"Team Head login created\", email, password });\n            load();\n          }}\n        />\n      )}\n      {secret && <PasswordModal {...secret} onClose={() => setSecret(null)} />}\n      {modal?.type === \"add\" && (\n        <FormModal\n          title={`Add member to ${team.name}`}\n          submitLabel=\"Add\"\n          fields={FIELDS}\n          onSubmit={async (v) => {\n            await houses.addMember(team.id, toBody(v));\n            await finish(\"Member added\");\n          }}\n          onClose={() => setModal(null)}\n        />\n      )}\n      {modal?.type === \"edit\" && (\n        <FormModal\n          title=\"Edit member\"\n          fields={FIELDS}\n          initial={{\n            name: modal.row.name,\n            phone: modal.row.phone || \"\",\n            job_title: modal.row.job_title || \"\",\n            is_team_head: Boolean(modal.row.is_team_head),\n          }}\n          onSubmit={async (v) => {\n            await houses.updateMember(modal.row.id, toBody(v));\n            await finish(\"Member saved\");\n          }}\n          onClose={() => setModal(null)}\n        />\n      )}\n    </div>\n  );\n}\n",
 "src/components/AppShell.jsx": "import { useEffect, useState } from \"react\";\nimport { NavLink, Outlet, useLocation, useNavigate } from \"react-router-dom\";\nimport { useAuth } from \"../features/auth/AuthContext.jsx\";\nimport HatSwitcher from \"./HatSwitcher.jsx\";\n\nfunction Logo() {\n  return (\n    <div className=\"flex items-center gap-2 text-lg font-black tracking-tight\">\n      <span className=\"grid h-8 w-8 place-items-center rounded-lg bg-brand text-white\">A</span>\n      <span>\n        Artha<span className=\"text-brand\">Tech</span>\n      </span>\n    </div>\n  );\n}\n\nexport default function AppShell() {\n  const { user, profile, can, logout } = useAuth();\n  const navigate = useNavigate();\n  const location = useLocation();\n  const [menuOpen, setMenuOpen] = useState(false); // mobile sidebar\n  const [userMenu, setUserMenu] = useState(false);\n\n  useEffect(() => setMenuOpen(false), [location.pathname]);\n\n  useEffect(() => {\n    if (!userMenu) return undefined;\n    const close = () => setUserMenu(false);\n    window.addEventListener(\"click\", close);\n    return () => window.removeEventListener(\"click\", close);\n  }, [userMenu]);\n\n  // The menu is built from permissions. Later modules get added to this list.\n  const nav = [\n    { to: \"/\", label: \"Dashboard\", end: true, show: true },\n    { to: \"/houses\", label: \"Houses\", show: can(\"house.create\") || can(\"project.view\") },\n    {\n      to: \"/users\",\n      label: \"Users\",\n      show: can(\"users.view\") || can(\"users.create.user\") || can(\"users.create.admin\"),\n    },\n    { to: \"/audit\", label: \"Audit log\", show: can(\"audit.view\") },\n  ].filter((i) => i.show);\n\n  const initials = (user?.full_name || user?.email || \"?\")\n    .split(/[\\s@]+/)\n    .filter(Boolean)\n    .slice(0, 2)\n    .map((s) => s[0].toUpperCase())\n    .join(\"\");\n\n  const sidebar = (\n    <nav className=\"flex h-full flex-col bg-ink p-5 text-white\">\n      <div className=\"mb-8 text-white\">\n        <Logo />\n      </div>\n      <div className=\"space-y-1\">\n        {nav.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            end={item.end}\n            className={({ isActive }) =>\n              `block rounded-lg px-3 py-2.5 text-sm font-semibold transition ${\n                isActive ? \"bg-brand text-white\" : \"text-white/70 hover:bg-white/10 hover:text-white\"\n              }`\n            }\n          >\n            {item.label}\n          </NavLink>\n        ))}\n      </div>\n      <p className=\"mt-auto text-xs text-white/35\">Money in rupees · v1 records only</p>\n    </nav>\n  );\n\n  return (\n    <div className=\"min-h-screen lg:pl-64\">\n      {/* Desktop sidebar */}\n      <aside className=\"fixed inset-y-0 left-0 z-30 hidden w-64 lg:block\">{sidebar}</aside>\n\n      {/* Mobile sidebar */}\n      {menuOpen && (\n        <div className=\"fixed inset-0 z-40 lg:hidden\">\n          <div className=\"absolute inset-0 bg-ink/60\" onClick={() => setMenuOpen(false)} />\n          <aside className=\"absolute inset-y-0 left-0 w-64\">{sidebar}</aside>\n        </div>\n      )}\n\n      <header className=\"sticky top-0 z-20 flex h-16 items-center justify-between border-b border-line bg-white/90 px-4 backdrop-blur sm:px-6\">\n        <div className=\"flex items-center gap-3\">\n          <button\n            onClick={() => setMenuOpen(true)}\n            aria-label=\"Open menu\"\n            className=\"grid h-10 w-10 cursor-pointer place-items-center rounded-lg border border-line lg:hidden\"\n          >\n            ☰\n          </button>\n          <div className=\"lg:hidden\">\n            <Logo />\n          </div>\n        </div>\n\n        <div className=\"flex items-center gap-3\">\n          <HatSwitcher />\n          <div className=\"relative\" onClick={(e) => e.stopPropagation()}>\n            <button\n              onClick={() => setUserMenu(!userMenu)}\n              aria-label=\"User menu\"\n              className=\"grid h-10 w-10 cursor-pointer place-items-center rounded-full bg-brand text-sm font-bold text-white hover:bg-brand-dark\"\n            >\n              {initials}\n            </button>\n            {userMenu && (\n              <div className=\"absolute right-0 z-40 mt-2 w-64 rounded-xl border border-line bg-white p-2 shadow-xl\">\n                <div className=\"border-b border-line px-3 pb-3 pt-2\">\n                  <p className=\"truncate text-sm font-bold\">{user?.full_name || \"—\"}</p>\n                  <p className=\"truncate text-xs text-ink/50\">{user?.email}</p>\n                  <p className=\"mt-1 text-xs font-semibold text-brand\">{profile?.role_name}</p>\n                </div>\n                <button\n                  onClick={() => navigate(\"/change-password\")}\n                  className=\"mt-1 block w-full cursor-pointer rounded-lg px-3 py-2.5 text-left text-sm font-semibold hover:bg-mist\"\n                >\n                  Change password\n                </button>\n                <button\n                  onClick={logout}\n                  className=\"block w-full cursor-pointer rounded-lg px-3 py-2.5 text-left text-sm font-semibold text-brand hover:bg-brand-light\"\n                >\n                  Log out\n                </button>\n              </div>\n            )}\n          </div>\n        </div>\n      </header>\n\n      <main className=\"mx-auto w-full max-w-6xl px-4 py-8 sm:px-6\">\n        <Outlet />\n      </main>\n    </div>\n  );\n}\n",
 "src/App.jsx": "import { Link, Route, Routes } from \"react-router-dom\";\nimport AppShell from \"./components/AppShell.jsx\";\nimport ProtectedRoute from \"./features/auth/ProtectedRoute.jsx\";\nimport LoginPage from \"./pages/LoginPage.jsx\";\nimport DashboardPage from \"./pages/DashboardPage.jsx\";\nimport UsersPage from \"./pages/UsersPage.jsx\";\nimport ChangePasswordPage from \"./pages/ChangePasswordPage.jsx\";\nimport HousesPage from \"./pages/HousesPage.jsx\";\nimport HouseDetailPage from \"./pages/HouseDetailPage.jsx\";\nimport ProjectDetailPage from \"./pages/ProjectDetailPage.jsx\";\nimport AuditLogPage from \"./pages/AuditLogPage.jsx\";\n\nfunction NotFound() {\n  return (\n    <div className=\"mx-auto max-w-md py-24 text-center\">\n      <p className=\"text-5xl font-black text-brand\">404</p>\n      <h1 className=\"mt-3 text-xl font-extrabold\">Page not found</h1>\n      <Link to=\"/\" className=\"mt-4 inline-block text-sm font-semibold text-brand hover:underline\">\n        Go to dashboard\n      </Link>\n    </div>\n  );\n}\n\nexport default function App() {\n  return (\n    <Routes>\n      <Route path=\"/login\" element={<LoginPage />} />\n      <Route\n        element={\n          <ProtectedRoute>\n            <AppShell />\n          </ProtectedRoute>\n        }\n      >\n        <Route index element={<DashboardPage />} />\n        <Route\n          path=\"users\"\n          element={\n            <ProtectedRoute anyOf={[\"users.view\", \"users.create.user\", \"users.create.admin\"]}>\n              <UsersPage />\n            </ProtectedRoute>\n          }\n        />\n        <Route path=\"houses\" element={<HousesPage />} />\n        <Route path=\"houses/:orgId\" element={<HouseDetailPage />} />\n        <Route path=\"projects/:projectId\" element={<ProjectDetailPage />} />\n        <Route\n          path=\"audit\"\n          element={\n            <ProtectedRoute anyOf={[\"audit.view\"]}>\n              <AuditLogPage />\n            </ProtectedRoute>\n          }\n        />\n        <Route path=\"change-password\" element={<ChangePasswordPage />} />\n        <Route path=\"*\" element={<NotFound />} />\n      </Route>\n    </Routes>\n  );\n}\n",
 "src/main.jsx": "import React from \"react\";\nimport { createRoot } from \"react-dom/client\";\nimport { BrowserRouter } from \"react-router-dom\";\nimport App from \"./App.jsx\";\nimport { AuthProvider } from \"./features/auth/AuthContext.jsx\";\nimport { ConfirmProvider } from \"./components/Confirm.jsx\";\nimport \"./index.css\";\n\ncreateRoot(document.getElementById(\"root\")).render(\n  <React.StrictMode>\n    <BrowserRouter>\n      <AuthProvider>\n        <ConfirmProvider>\n          <App />\n        </ConfirmProvider>\n      </AuthProvider>\n    </BrowserRouter>\n  </React.StrictMode>\n);\n"
};
